{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfa;--card:#fff;--muted:#6b6b6b;--accent:#6a7c5a;--accent-2:#c9d6b5;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#222;background:var(--bg)}
    .page{min-height:100%;display:flex;flex-direction:column}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:linear-gradient(180deg,transparent,transparent);position:sticky;top:0;backdrop-filter:blur(6px);z-index:10}
    .brand{display:flex;align-items:center;gap:14px}
    .logo{width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,var(--accent-2),#eef4e6);display:flex;align-items:center;justify-content:center;font-weight:700;color:#fff}
    nav a{margin-left:18px;color:var(--muted);text-decoration:none;font-size:15px}
    .hero{padding:44px 28px;background-image:url('assets/img/pattern.svg');background-repeat:no-repeat;background-position:top right;background-size:320px}
    .hero .inner{max-width:920px}
    h1{margin:0 0 8px;font-size:28px;letter-spacing:-0.2px}
    p.lead{margin:0;color:var(--muted);font-size:15px}
    main{padding:28px}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:start}
    .card{background:var(--card);padding:20px;border-radius:12px;box-shadow:0 6px 18px rgba(25,25,25,0.04)}
    .pillars{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:18px}
    .pill{padding:14px;border-radius:10px;background:linear-gradient(180deg,#fff,#fbfff7);font-size:14px}
    .reveal{opacity:0;transform:translateY(18px);transition:opacity 500ms ease,transform 500ms ease}
    .reveal.in-view{opacity:1;transform:none}
    .packages{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin-top:16px}
    .pkg{padding:18px;border-radius:10px;border:1px solid #eef1ea}
    .price{font-weight:700;font-size:18px;color:var(--accent)}
    footer{padding:20px 28px;margin-top:28px;color:var(--muted);font-size:13px}
    /* session planner */
    .planner h3{margin:0 0 8px}
    .field{margin-bottom:10px}
    label{display:block;font-size:13px;margin-bottom:6px;color:#333}
    input[type=text],select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #e6e9e3;font-size:14px}
    .controls{display:flex;gap:8px;margin-top:8px}
    button{background:var(--accent);color:#fff;border:none;padding:10px 12px;border-radius:8px;cursor:pointer}
    button.secondary{background:#fff;color:var(--accent);border:1px solid #e5e8e0}
    .muted-note{font-size:13px;color:var(--muted);margin-top:8px}
    @media (max-width:880px){.grid{grid-template-columns:1fr}}  
    /* reduced motion preference */
    @media (prefers-reduced-motion: reduce){.reveal{transition:none;opacity:1;transform:none}}
  </style>
</head>
<body>
  <div class="page">
    <header>
      <div class="brand">
        <div class="logo">A</div>
        <div>
          <div style="font-weight:700">{{BUSINESS_NAME}}</div>
          <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
        </div>
      </div>
      <nav>
        <a href="index.html">Home</a>
        <a href="services.html">Offerings</a>
        <a href="blends.html">Essences</a>
        <a href="shop.html">Apothecary</a>
        <a href="pricing.html">Plans</a>
        <a href="book.html">Schedule</a>
        <a href="contact.html">Reach</a>
      </nav>
    </header>

    <section class="hero">
      <div class="inner card">
        <h1>Therapeutic sessions crafted around your context</h1>
        <p class="lead">Tailored aromatherapy sessions that may support moments of ease. Choose single-session focus work or layered session plans for repeat support.</p>
        <div style="margin-top:14px">
          <a href="{{PRIMARY_CTA_URL}}" style="display:inline-block;padding:10px 14px;border-radius:10px;background:var(--accent);color:#fff;text-decoration:none">{{PRIMARY_CTA_LABEL}}</a>
          <a href="book.html" style="margin-left:10px;color:var(--muted);text-decoration:none">Book a consult</a>
        </div>
      </div>
    </section>

    <main>
      <div class="grid">
        <div>
          <section class="card reveal" id="overview">
            <h2 style="margin-top:0">What we offer</h2>
            <div class="pillars">
              <div class="pill">
                <strong>Focused Session</strong>
                <div class="muted-note">30 minutes to address a single intent; scent profile and brief practice included.</div>
              </div>
              <div class="pill">
                <strong>Deep Day</strong>
                <div class="muted-note">90–120 minute immersive exploration with a custom blend kit to continue at home.</div>
              </div>
              <div class="pill">
                <strong>Series Plan</strong>
                <div class="muted-note">A 3–6 visit pathway to layer practices and refine a home protocol.</div>
              </div>
            </div>

            <div class="packages" style="margin-top:16px">
              <div class="pkg">
                <div style="font-size:13px;color:var(--muted)">Focused Session</div>
                <div class="price">$95 — 30 min</div>
                <div class="muted-note">A guided mini-session with a tailored inhalation or diffusion practice.</div>
              </div>
              <div class="pkg">
                <div style="font-size:13px;color:var(--muted)">Deep Day</div>
                <div class="price">$260 — extended</div>
                <div class="muted-note">Includes take-home sample blend and written plan.</div>
              </div>
              <div class="pkg">
                <div style="font-size:13px;color:var(--muted)">Series Plan</div>
                <div class="price">From $240 — 3 sessions</div>
                <div class="muted-note">Discounted block to build continuity and refine scent strategies.</div>
              </div>
            </div>

          </section>

          <section class="card reveal" style="margin-top:18px" id="case-notes">
            <h2 style="margin-top:0">Practitioner notes & approach</h2>
            <p class="muted-note">Each plan is personalized, safety-forward, and practical. We emphasize low-concentration protocols and stepwise introduction to new aromas. Sessions may support relaxation, gentle focus, or an uplift in mood; they are not medical therapies.</p>
          </section>

          <section class="card reveal" style="margin-top:18px" id="faq">
            <h2 style="margin-top:0">Safety & FAQs</h2>
            <ul style="padding-left:18px;color:var(--muted)">
              <li><strong>Are sessions medical?</strong> No. Aromatherapy sessions are supportive and complementary and may support well-being, but they are not medical treatments.</li>
              <li><strong>Dilution guidance:</strong> Home blends typically start 0.5–2% for adults. For sensitive skin, pregnancy, children, or pets at home, we advise lower dilutions and specific ingredient avoidance.</li>
              <li><strong>Patch test:</strong> Always perform a small skin patch test before topical use: dilute, apply a small amount behind the ear or inner forearm, and wait 24 hours.</li>
              <li><strong>Pregnancy & medications:</strong> Some aromas are contraindicated in pregnancy or certain conditions. Disclose pregnancy, medications, and major health considerations before sessions.</li>
              <li><strong>Pets:</strong> Many essential oils can be harmful to pets. We provide pet-safe alternatives and diffusion guidelines when animals share the space.</li>
            </ul>
          </section>
        </div>

        <aside class="card planner reveal" id="planner-side">
          <h3>Session Planner</h3>
          <form id="session-planner">
            <div class="field"><label for="name">Name (optional)</label><input id="name" type="text" placeholder="Your name"/></div>
            <div class="field"><label for="goal">Primary intent</label><select id="goal"><option>Choose an intent…</option><option value="ease">Manage mild stress or nervous tension</option><option value="sleep">Support sleep onset</option><option value="focus">Short-term focus or clarity</option><option value="mood">Gentle mood lift</option><option value="tension">Muscle tension support</option><option value="custom">Custom exploration</option></select></div>
            <div class="field"><label>Session length</label><select id="duration"><option value="5">5 min micro</option><option value="15">15 min focused</option><option value="30" selected>30 min session</option><option value="60">60 min extended</option></select></div>
            <div class="field"><label>Considerations</label>
              <div style="display:flex;flex-direction:column;gap:6px">
                <label><input type="checkbox" id="pregnancy"/> Pregnancy / breastfeeding</label>
                <label><input type="checkbox" id="sensitive"/> Sensitive skin</label>
                <label><input type="checkbox" id="pets"/> Pets at home</label>
              </div>
            </div>
            <div class="field"><label>Preferred scent notes</label>
              <div style="display:flex;flex-wrap:wrap;gap:6px">
                <label><input type="checkbox" name="note" value="citrus"/> Citrus</label>
                <label><input type="checkbox" name="note" value="floral"/> Floral</label>
                <label><input type="checkbox" name="note" value="wood"/> Woody</label>
                <label><input type="checkbox" name="note" value="herbal"/> Herbal</label>
                <label><input type="checkbox" name="note" value="spice"/> Warm spice</label>
                <label><input type="checkbox" name="note" value="fresh"/> Fresh / green</label>
              </div>
            </div>

            <div class="controls">
              <button type="button" id="build-plan">Create plan</button>
              <button type="button" class="secondary" id="clear-plan">Reset</button>
            </div>

            <div style="margin-top:10px">
              <label for="plan-output">Plan summary (plaintext)</label>
              <textarea id="plan-output" rows="8" placeholder="Your session plan will appear here"></textarea>
              <div style="display:flex;gap:8px;margin-top:8px">
                <button type="button" id="copy-plan">Copy</button>
                <button type="button" id="download-plan" class="secondary">Download .txt</button>
              </div>
              <div class="muted-note">This tool builds a simple, printable plan and safety notes you can bring to a session.</div>
            </div>
          </form>
        </aside>
      </div>
    </main>

    <footer>
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px">
        <div>&copy; <span id="year"></span> {{BUSINESS_NAME}} • <span style="color:var(--muted)">{{CITY}}, {{STATE}}</span></div>
        <div style="color:var(--muted)">Phone: {{PHONE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      </div>
    </footer>
  </div>

  <script>
    // Scroll reveal with reduced-motion support
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const reveals = document.querySelectorAll('.reveal');
      if(prefersReduced){ reveals.forEach(r=>r.classList.add('in-view')); return; }
      const io = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{ if(e.isIntersecting) { e.target.classList.add('in-view'); io.unobserve(e.target); } });
      },{threshold:0.12});
      reveals.forEach(r=>io.observe(r));
    })();

    // Session Planner logic
    (function(){
      const btn = document.getElementById('build-plan');
      const output = document.getElementById('plan-output');
      const copyBtn = document.getElementById('copy-plan');
      const downloadBtn = document.getElementById('download-plan');
      const clearBtn = document.getElementById('clear-plan');

      const blendMap = {
        ease: {name:'Calm Thread', notes:'lavender, sweet marjoram, bergamot'},
        sleep: {name:'Dusk Ease', notes:'lavender, cedarwood, vetiver'},
        focus: {name:'Bright Line', notes:'rosemary, lemon, black pepper'},
        mood: {name:'Sunsmall', notes:'orange, geranium, petitgrain'},
        tension: {name:'Warm Support', notes:'peppermint (low), helichrysum, fir'},
        custom: {name:'Custom Compose', notes:'practitioner-led selection'}
      };

      function gather(){
        const name = document.getElementById('name').value.trim();
        const goal = document.getElementById('goal').value;
        const duration = document.getElementById('duration').value;
        const pregnancy = document.getElementById('pregnancy').checked;
        const sensitive = document.getElementById('sensitive').checked;
        const pets = document.getElementById('pets').checked;
        const notes = Array.from(document.querySelectorAll('input[name="note"]:checked')).map(n=>n.value);
        return {name,goal,duration,pregnancy,sensitive,pets,notes};
      }

      function recommend(opts){
        const base = blendMap[opts.goal] || blendMap.custom;
        let dilution = '1% (mild)';
        if(opts.sensitive || opts.pregnancy || opts.pets) dilution = '0.25–0.5% (very low)';
        else if(opts.duration==='5') dilution = '0.5–1%';
        else if(opts.duration==='60') dilution = '1–2%';

        const method = opts.duration==='5' ? 'Personal inhaler or brief sniffing ritual' : 'Diffusion or inhalation and guided 1:1 practice';

        let notesLine = opts.notes.length? 'Preferred notes: '+opts.notes.join(', ')+'.' : '';
        if(opts.pets) notesLine += ' Use pet-safe alternatives; avoid diffusing for prolonged periods.';
        if(opts.pregnancy) notesLine += ' Some oils are contraindicated in pregnancy; consult before topical use.';

        return {
          title: base.name,
          ingredients: base.notes,
          dilution,
          method,
          notesLine
        };
      }

      function buildText(){
        const opts = gather();
        if(!opts.goal || opts.goal==='Choose an intent…') { output.value = 'Please select an intent to build a plan.'; return; }
        const rec = recommend(opts);
        const who = opts.name ? opts.name : 'Client';
        const lines = [];
        lines.push(who + ' — Aromatherapy session plan');
        lines.push('Intent: '+(opts.goal));
        lines.push('Recommended blend: '+rec.title);
        lines.push('Suggested notes/constituents: '+rec.ingredients);
        lines.push('Dilution guideline: '+rec.dilution);
        lines.push('Delivery: '+rec.method);
        lines.push('Session outline:');
        lines.push('  1) Brief intake and safety check (patch test if topical).');
        lines.push('  2) Guided inhalation or diffusion practice for '+opts.duration+' minutes.');
        lines.push('  3) Short reflection and written notes to take home.');
        if(rec.notesLine) lines.push('Safety notes: '+rec.notesLine);
        lines.push('\nRemember: these practices may support well-being but are not a substitute for medical care. Avoid using undiluted oils on the skin.');
        output.value = lines.join('\n');
      }

      btn.addEventListener('click', buildText);
      clearBtn.addEventListener('click', ()=>{ document.getElementById('session-planner').reset(); output.value=''; });

      copyBtn.addEventListener('click', async ()=>{
        try{ await navigator.clipboard.writeText(output.value || ''); copyBtn.textContent='Copied'; setTimeout(()=>copyBtn.textContent='Copy',1400);}catch(e){ alert('Copy failed — select and copy manually.'); }
      });

      downloadBtn.addEventListener('click', ()=>{
        const blob = new Blob([output.value || ''],{type:'text/plain'});
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a'); a.href=url; a.download='session-plan.txt'; document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
      });

      // set year
      document.getElementById('year').textContent = new Date().getFullYear();
    })();
  </script>
</body>
</html>"} 
{"path":"blends.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Essences — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f8fbf7;--card:#fff;--muted:#5f6b59;--accent:#4e6a45;--accent-soft:#dbe7d1}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;background:var(--bg);color:#1f271f}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 24px;background:transparent}
    .logo{width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,var(--accent-soft),#fff);display:flex;align-items:center;justify-content:center;font-weight:700;color:var(--accent)}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none}
    main{max-width:1100px;margin:18px auto;padding:0 16px}
    .top{display:flex;gap:18px;align-items:flex-start}
    .lead{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 6px 16px rgba(18,22,16,0.04);flex:1}
    .aside{width:320px}
    .blend-list{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-top:14px}
    .blend{background:var(--card);padding:14px;border-radius:10px;border:1px solid #eef2ea}
    .blend h4{margin:0 0 6px}
    .muted{color:var(--muted);font-size:13px}
    .reveal{opacity:0;transform:translateY(12px);transition:opacity 480ms ease,transform 480ms ease}
    .reveal.in-view{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){.reveal{transition:none;opacity:1;transform:none}}
    @media (max-width:880px){.top{flex-direction:column}.blend-list{grid-template-columns:1fr}.aside{width:100%}}
    .cta{display:inline-block;padding:10px 12px;background:var(--accent);color:#fff;border-radius:8px;text-decoration:none}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">E</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Essences</a>
      <a href="shop.html">Apothecary</a>
      <a href="pricing.html">Plans</a>
      <a href="book.html">Schedule</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main>
    <div class="top">
      <div class="lead card reveal">
        <h2 style="margin-top:0">Our curated essences</h2>
        <p class="muted">A collection of ready blends and single notes for inhalation or dilution. Each blend is crafted with safety margins and guidance for at-home use. Choose a sample, or request a bespoke composition during a session.</p>

        <div style="margin-top:12px;display:flex;gap:8px;flex-wrap:wrap">
          <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a style="align-self:center;color:var(--muted);text-decoration:none" href="services.html">See session types</a>
        </div>

        <div class="blend-list" style="margin-top:12px">
          <article class="blend reveal">
            <h4>Calm Thread</h4>
            <div class="muted">lavender • bergamot • sweet marjoram</div>
            <p class="muted" style="margin-top:8px">A light, floral-citrus composition designed for short inhalation practices. Suggested dilution: 0.5–1% for adults.</p>
          </article>

          <article class="blend reveal">
            <h4>Dusk Ease</h4>
            <div class="muted">lavender • cedarwood • vetiver</div>
            <p class="muted" style="margin-top:8px">Gentle, grounding profile suitable for evening routines. Avoid topical use in pregnancy without guidance; diffusion preferred at low output.</p>
          </article>

          <article class="blend reveal">
            <h4>Bright Line</h4>
            <div class="muted">rosemary • lemon • black pepper</div>
            <p class="muted" style="margin-top:8px">Crisp and clarifying; useful for short bursts of focus. Use caution with blood-thinning medications—discuss with practitioner.</p>
          </article>

          <article class="blend reveal">
            <h4>Sunsmall</h4>
            <div class="muted">sweet orange • geranium • petitgrain</div>
            <p class="muted" style="margin-top:8px">Bright and gentle uplift. Pet-safe alternatives available; consult notes before home diffusion around animals.</p>
          </article>
        </div>
      </div>

      <aside class="aside reveal card" style="padding:16px">
        <h3 style="margin-top:0">Quick planner</h3>
        <p class="muted">Build a short plan and capture dilution and steps to try at home.</p>

        <div style="margin-top:10px">
          <label for="bp-goal" style="display:block;font-size:13px;margin-bottom:6px">Intent</label>
          <select id="bp-goal" style="width:100%;padding:10px;border-radius:8px;border:1px solid #e6e9e3;margin-bottom:8px">
            <option value="ease">Manage stress</option>
            <option value="sleep">Support sleep</option>
            <option value="focus">Short-term focus</option>
            <option value="mood">Mood lift</option>
          </select>
          <label style="display:block;font-size:13px;margin-bottom:6px">Notes (optional)</label>
          <input id="bp-notes" type="text" placeholder="e.g., citrus preference" style="width:100%;padding:10px;border-radius:8px;border:1px solid #e6e9e3"/>
          <div style="display:flex;gap:8px;margin-top:8px">
            <button id="bp-build">Make plan</button>
            <button id="bp-copy" class="secondary" style="border:1px solid #e6e9e3;background:#fff;color:var(--accent);">Copy</button>
          </div>
          <textarea id="bp-out" rows="5" style="margin-top:8px;width:100%;padding:10px;border-radius:8px;border:1px solid #e6e9e3"></textarea>
        </div>
      </aside>
    </div>

    <section style="margin-top:18px">
      <div class="card reveal" style="padding:14px">
        <h3 style="margin-top:0">Blend notes & guidance</h3>
        <p class="muted">Each blend includes recommended dilution and suggested delivery method. For topical use, always dilute appropriately and perform a patch test. If you are pregnant, nursing, have a chronic condition, or have pets in the home, let us know before applying or diffusing a new oil.</p>
      </div>
    </section>

    <section style="margin-top:12px">
      <div class="card reveal" style="padding:14px">
        <h3 style="margin-top:0">Request a bespoke blend</h3>
        <p class="muted">If none of the premade blends fit, book a custom composition during a session. We prioritize simple, safe formulations with clear take-home instructions.</p>
      </div>
    </section>
  </main>

  <script>
    // Scroll reveal
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('.reveal');
      if(prefersReduced){ items.forEach(i=>i.classList.add('in-view')); return; }
      const io = new IntersectionObserver((entries)=>{ entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('in-view'); io.unobserve(e.target); } }); },{threshold:0.08});
      items.forEach(i=>io.observe(i));
    })();

    // Small planner in blends
    (function(){
      const build = document.getElementById('bp-build');
      const copy = document.getElementById('bp-copy');
      const out = document.getElementById('bp-out');

      const map = { ease: 'Calm Thread — 0.5–1% dilution. Inhalation or brief diffusion (10–15 min).', sleep: 'Dusk Ease — 0.5–1% dilution. Diffuse low for 30 min before bed.', focus: 'Bright Line — 0.5–1% dilution. Short inhalation or desk diffuser for bursts.', mood: 'Sunsmall — 0.5–1% dilution. Inhaler or diffuser for short uplifting moments.' };

      build.addEventListener('click', ()=>{
        const g = document.getElementById('bp-goal').value;
        const notes = document.getElementById('bp-notes').value.trim();
        let text = 'Plan for: ' + (g||'') + '\n' + (map[g]||'Custom approach');
        if(notes) text += '\nPreferences: ' + notes;
        text += '\n\nSafety: patch test before topical use; avoid prolonged diffusion around pets.';
        out.value = text;
      });

      copy.addEventListener('click', async ()=>{ try{ await navigator.clipboard.writeText(out.value); copy.textContent='Copied'; setTimeout(()=>copy.textContent='Copy',1200);}catch(e){ alert('Unable to copy'); } });
    })();
  </script>
</body>
</html>"} 
{"path":"shop.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Apothecary — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff;--muted:#687064;--card:#fff;--accent:#5a6f4f}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;background:var(--bg);color:#111}
    header{display:flex;align-items:center;justify-content:space-between;padding:14px 20px}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none}
    main{max-width:1100px;margin:12px auto;padding:0 18px}
    .catalog{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
    .product{background:#fbfff9;padding:14px;border-radius:12px;border:1px solid #eef2ea}
    .product h4{margin:0 0 6px}
    .muted{color:var(--muted);font-size:13px}
    .reveal{opacity:0;transform:translateY(14px);transition:opacity 480ms ease,transform 480ms ease}
    .reveal.in-view{opacity:1;transform:none}
    @media (max-width:980px){.catalog{grid-template-columns:repeat(2,1fr)}}
    @media (max-width:640px){.catalog{grid-template-columns:1fr}}    
    .plan-trigger{position:fixed;right:18px;bottom:18px;background:var(--accent);color:#fff;border-radius:999px;padding:12px 14px;box-shadow:0 8px 22px rgba(20,20,20,0.12);cursor:pointer}
    .modal{position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:rgba(10,10,10,0.36)}
    .modal.open{display:flex}
    .modal .sheet{width:480px;background:#fff;padding:18px;border-radius:12px}
    .small{font-size:13px;color:var(--muted)}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div style="width:40px;height:40px;border-radius:8px;background:linear-gradient(135deg,#eaf2e4,#fff);display:flex;align-items:center;justify-content:center;font-weight:700;color:var(--accent)">A</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Essences</a>
      <a href="shop.html">Apothecary</a>
      <a href="pricing.html">Plans</a>
      <a href="book.html">Schedule</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>
  <main>
    <h2 style="margin-top:6px">Apothecary</h2>
    <p class="muted">Thoughtful essentials and simple tools to support short scent practices at home. Each product page includes dilution and safety notes.</p>

    <section style="margin-top:12px" class="catalog">
      <article class="product reveal">
        <h4>Sample set — 5 x 2ml</h4>
        <div class="muted">Try four blends + one single note. Helps you discover preferences.</div>
        <div style="margin-top:8px;font-weight:700">$24</div>
      </article>

      <article class="product reveal">
        <h4>10ml Calm Thread</h4>
        <div class="muted">A premixed vial for inhalation and home dilution. Comes with dilution card.</div>
        <div style="margin-top:8px;font-weight:700">$18</div>
      </article>

      <article class="product reveal">
        <h4>Glass personal inhaler</h4>
        <div class="muted">Refillable inhaler for quick access to a chosen blend.</div>
        <div style="margin-top:8px;font-weight:700">$12</div>
      </article>

      <article class="product reveal">
        <h4>Mini diffuser</h4>
        <div class="muted">Low-output diffuser for bedside or desk use.</div>
        <div style="margin-top:8px;font-weight:700">$38</div>
      </article>

      <article class="product reveal">
        <h4>Roller bottle kit</h4>
        <div class="muted">Empty rollers + stickers for labeling your blends.</div>
        <div style="margin-top:8px;font-weight:700">$16</div>
      </article>

      <article class="product reveal">
        <h4>Gift card</h4>
        <div class="muted">Give a session credit or product credit. Redeemable online or in a booking.</div>
        <div style="margin-top:8px;font-weight:700">From $50</div>
      </article>
    </section>

    <section style="margin-top:18px" class="reveal card" id="safety" style="padding:14px">
      <div style="background:#fff;padding:14px;border-radius:10px;border:1px solid #eef2ea">
        <h3 style="margin-top:0">Safe use reminders</h3>
        <p class="small">Products are sold with guidance. For topical use dilute appropriately; test a small patch of skin and wait 24 hours. If pregnant, nursing, or medicated, consult before topical application. If you have pets, ask for pet-safe options — not all essential oils are safe for animals.</p>
      </div>
    </section>

  </main>

  <button class="plan-trigger" id="open-planner">Plan a session</button>

  <div class="modal" id="planner-modal" aria-hidden="true">
    <div class="sheet">
      <h3 style="margin-top:0">Session Planner</h3>
      <p class="small">Build a plan and copy a plaintext summary you can email or bring to a consult.</p>
      <div style="margin-top:8px">
        <label class="small">Intent</label>
        <select id="m-goal" style="width:100%;padding:10px;border-radius:8px;border:1px solid #e6e9e3;margin-bottom:8px">
          <option value="ease">Manage stress</option>
          <option value="sleep">Support sleep</option>
          <option value="focus">Focus</option>
          <option value="mood">Mood lift</option>
        </select>
        <label class="small">Notes</label>
        <input id="m-notes" type="text" style="width:100%;padding:10px;border-radius:8px;border:1px solid #e6e9e3;margin-bottom:8px" placeholder="Citrus preferred" />
        <div style="display:flex;gap:8px">
          <button id="m-build">Create</button>
          <button id="m-copy" class="secondary" style="background:#fff;border:1px solid #eee;color:var(--accent)">Copy</button>
          <button id="m-close" style="margin-left:auto;background:#eee;color:#111;border-radius:8px;padding:8px 10px">Close</button>
        </div>
        <textarea id="m-out" rows="7" style="width:100%;margin-top:8px;padding:10px;border-radius:8px;border:1px solid #e6e9e3"></textarea>
      </div>
    </div>
  </div>

  <script>
    // reveal
    (function(){
      const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const nodes = document.querySelectorAll('.reveal');
      if(reduced){ nodes.forEach(n=>n.classList.add('in-view')); return; }
      const io = new IntersectionObserver((entries)=>{ entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('in-view'); io.unobserve(e.target); } }); },{threshold:0.08});
      nodes.forEach(n=>io.observe(n));
    })();

    // modal planner
    (function(){
      const open = document.getElementById('open-planner');
      const modal = document.getElementById('planner-modal');
      const close = document.getElementById('m-close');
      const build = document.getElementById('m-build');
      const copy = document.getElementById('m-copy');
      const out = document.getElementById('m-out');

      open.addEventListener('click', ()=>{ modal.classList.add('open'); modal.setAttribute('aria-hidden','false'); });
      close.addEventListener('click', ()=>{ modal.classList.remove('open'); modal.setAttribute('aria-hidden','true'); });
      modal.addEventListener('click', (e)=>{ if(e.target===modal){ modal.classList.remove('open'); modal.setAttribute('aria-hidden','true'); } });

      const map = { ease: 'Calm Thread — 0.5–1% dilution, inhalation or short diffusion.', sleep: 'Dusk Ease — 0.5–1% dilution, diffuse low for 20–30 minutes before bed.', focus: 'Bright Line — use in a personal inhaler or brief desk diffusion.', mood: 'Sunsmall — small inhaler or roller diluted to 0.5–1%.' };

      build.addEventListener('click', ()=>{
        const g = document.getElementById('m-goal').value;
        const n = document.getElementById('m-notes').value.trim();
        let text = 'Session plan — Intent: ' + g + '\n' + (map[g]||'Custom') + '\n';
        if(n) text += 'Preferences: '+n+'\n';
        text += '\nSafety: patch test topical uses; choose pet-safe blends when animals are present.';
        out.value = text;
      });

      copy.addEventListener('click', async ()=>{ try{ await navigator.clipboard.writeText(out.value); copy.textContent='Copied'; setTimeout(()=>copy.textContent='Copy',1200);}catch(e){ alert('Copy failed'); } });
    })();
  </script>
</body>
</html>"} 
